(47811, 'Numbers 2:3', 'Numbers', 2, 3, 'د یهودا د کمپ ډلې دې په ختیځ کې د لمرخاته خواته د خپل بیرغ لاندې خېمې ودروي. د یهودا د خلکو مشر د عمیناداب زوی نحشون دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_3.mp3', '', 1761754199, 1761754199),
(47812, 'Numbers 2:4', 'Numbers', 2, 4, 'د هغه د ډلې شمېر ۷۴۶۰۰ تنه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_4.mp3', '', 1761754199, 1761754199),
(47813, 'Numbers 2:5', 'Numbers', 2, 5, 'د یساکار قبیله به د هغوی په څنګ کې خېمې ودروي. د یساکار د خلکو مشر د صوغر زوی نتناییل دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_5.mp3', '', 1761754199, 1761754199),
(47814, 'Numbers 2:6', 'Numbers', 2, 6, 'د هغه د ډلې شمېر ۵۴۴۰۰ تنه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_6.mp3', '', 1761754199, 1761754199),
(47815, 'Numbers 2:7', 'Numbers', 2, 7, 'ورپسې به د زبولون قبیله وي. د زبولون د خلکو مشر د حیلون زوی الیاب دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_7.mp3', '', 1761754199, 1761754199),
(47816, 'Numbers 2:8', 'Numbers', 2, 8, 'د هغه د ډلې شمېر ۵۷۴۰۰ تنه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_8.mp3', '', 1761754199, 1761754199),
(47817, 'Numbers 2:9', 'Numbers', 2, 9, 'هغه ټول کسان چې د یهودا کمپ ته د هغوی د ډلو له مخې ورکړل شوي دي، د هغوی شمېر ۱۸۶۴۰۰ تنه دی. لومړی به دوی روان شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_9.mp3', '', 1761754199, 1761754199),
(47818, 'Numbers 2:10', 'Numbers', 2, 10, 'د روبین د کمپ ډلې به په جنوب کې د خپل بیرغ لاندې وي. د روبین د خلکو مشر د شدییور زوی الیصور دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_10.mp3', '', 1761754199, 1761754199),
(47819, 'Numbers 2:11', 'Numbers', 2, 11, 'د هغه د ډلې شمېر ۴۶۵۰۰ تنه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_11.mp3', '', 1761754199, 1761754199),
(47820, 'Numbers 2:12', 'Numbers', 2, 12, 'د شمعون قبیله به د هغوی په څنګ کې خېمې ودروي. د شمعون د خلکو مشر د صوریشدای زوی شلومییل دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_12.mp3', '', 1761754199, 1761754199),
(47821, 'Numbers 2:13', 'Numbers', 2, 13, 'د هغه د ډلې شمېر ۵۹۳۰۰ تنه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_13.mp3', '', 1761754199, 1761754199),
(47822, 'Numbers 2:14', 'Numbers', 2, 14, 'ورپسې به د جاد قبیله وي. د جاد د خلکو مشر د دعویل زوی الیاساف دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_14.mp3', '', 1761754199, 1761754199),
(47823, 'Numbers 2:15', 'Numbers', 2, 15, 'د هغه د ډلې شمېر ۴۵۶۵۰ تنه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_15.mp3', '', 1761754199, 1761754199),
(47824, 'Numbers 2:16', 'Numbers', 2, 16, 'هغه ټول کسان چې د روبین کمپ ته د هغوی د ډلو له مخې ورکړل شوي دي، د هغوی شمېر ۱۵۱۴۵۰ تنه دی. دوهم به دوی روان شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_16.mp3', '', 1761754199, 1761754199),
(47825, 'Numbers 2:17', 'Numbers', 2, 17, 'بیا د لومړنیو او اخرنیو دوو کمپونو په منځ کې دې لاویان روان شي او سپېڅلې خېمه دې یوسي. هر کمپ دې په هماغه ترتیب سره روان شي لکه څنګه چې هغوی خېمې ودروي. هر یو به په خپل ځای کې د خپل بیرغ لاندې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_17.mp3', '', 1761754199, 1761754199),
(47826, 'Numbers 2:18', 'Numbers', 2, 18, 'د افرایم د کمپ ډلې به په لوېدیځ کې د خپل بیرغ لاندې وي. د افرایم د خلکو مشر د عمیهود زوی الیشمع دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_18.mp3', '', 1761754199, 1761754199),
(47827, 'Numbers 2:19', 'Numbers', 2, 19, 'د هغه د ډلې شمېر ۴۰۵۰۰ تنه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_19.mp3', '', 1761754199, 1761754199),
(47828, 'Numbers 2:20', 'Numbers', 2, 20, 'د منسي قبیله به د هغوی په څنګ کې وي. د منسي د خلکو مشر د فدهصور زوی جملی ییل دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_20.mp3', '', 1761754199, 1761754199),
(47829, 'Numbers 2:21', 'Numbers', 2, 21, 'د هغه د ډلې شمېر ۳۲۲۰۰ تنه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_21.mp3', '', 1761754199, 1761754199),
(47830, 'Numbers 2:22', 'Numbers', 2, 22, 'ورپسې به د بنیامین قبیله وي. د بنیامین د خلکو مشر د جدعوني زوی ابیدان دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_22.mp3', '', 1761754199, 1761754199),
(47831, 'Numbers 2:23', 'Numbers', 2, 23, 'د هغه د ډلې شمېر ۳۵۴۰۰ تنه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_23.mp3', '', 1761754199, 1761754199),
(47832, 'Numbers 2:24', 'Numbers', 2, 24, 'هغه ټول کسان چې د افرایم کمپ ته د هغوی د ډلو له مخې ورکړل شوي دي، د هغوی شمېر ۱۰۸۱۰۰ تنه دی. درېم به دوی روان شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_24.mp3', '', 1761754199, 1761754199),
(47833, 'Numbers 2:25', 'Numbers', 2, 25, 'د دان د کمپ ډلې به په شمال کې د خپل بیرغ لاندې وي. د دان د خلکو مشر د عمیشدای زوی اخیعزر دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_25.mp3', '', 1761754199, 1761754199),
(47834, 'Numbers 2:26', 'Numbers', 2, 26, 'د هغه د ډلې شمېر ۶۲۷۰۰ تنه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_26.mp3', '', 1761754199, 1761754199),
(47835, 'Numbers 2:27', 'Numbers', 2, 27, 'د اشیر قبیله به د هغوی په څنګ کې خېمې ودروي. د اشیر د خلکو مشر د عکران زوی فجعییل دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_27.mp3', '', 1761754199, 1761754199),
(47836, 'Numbers 2:28', 'Numbers', 2, 28, 'د هغه د ډلې شمېر ۴۱۵۰۰ تنه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_28.mp3', '', 1761754199, 1761754199),
(47837, 'Numbers 2:29', 'Numbers', 2, 29, 'ورپسې به د نفتالي قبیله وي. د نفتالي د خلکو مشر د عینان زوی اخیرع دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_29.mp3', '', 1761754199, 1761754199),
(47838, 'Numbers 2:30', 'Numbers', 2, 30, 'د هغه د ډلې شمېر ۵۳۴۰۰ تنه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_30.mp3', '', 1761754199, 1761754199),
(47839, 'Numbers 2:31', 'Numbers', 2, 31, 'هغه ټول کسان چې د دان کمپ ته ورکړل شوي دي، د هغوی شمېر ۱۵۷۶۰۰ تنه دی. هغوی به د خپلو بیرغونو لاندې په اخر کې روان شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_31.mp3', '', 1761754199, 1761754199),
(47840, 'Numbers 2:32', 'Numbers', 2, 32, 'نو دا د اسراییلو د قوم سرشمېرنه وه چې د هغوی د کورنیو له مخې تر سره شوه. هغه ټول خلک چې په ډلو ډلو په کمپونو کې وو، شمېر یې ۶۰۳۵۵۰ تنه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_32.mp3', '', 1761754199, 1761754199),
(47841, 'Numbers 2:33', 'Numbers', 2, 33, 'لکه څنګه چې څښتن موسی ته امر کړی ؤ لاویان د نورو اسراییلیانو سره یوځای ونه شمېرل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_33.mp3', '', 1761754199, 1761754199),
(47842, 'Numbers 2:34', 'Numbers', 2, 34, 'نو د اسراییلو قوم هغه ټول کارونه سرته ورسول چې څښتن موسی ته امر کړی ؤ. په دې ډول هغوی هر یو د خپل بیرغ لاندې خېمې ودرولې او د خپلې طایفې او خپلې کورنۍ سره روان شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers2_verse_34.mp3', '', 1761754199, 1761754199),
(47843, 'Ezekiel 22:1', 'Ezekiel', 22, 1, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_1.mp3', '', 1761754199, 1761754199),
(47844, 'Ezekiel 22:2', 'Ezekiel', 22, 2, '«ای فاني انسانه، ایا ته تیار یې چې د وینې تویونې څخه د ډک ښار په هکله قضاوت وکړې؟ هغه ته خپل ټول د کرکې وړ کارونه چې کړي یې دي، ور په یاد کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_2.mp3', '', 1761754199, 1761754199),
(47845, 'Ezekiel 22:3', 'Ezekiel', 22, 3, 'دې ښار ته ووایه چې زه څښتن تعالی داسې وایم: ‹ای ښاره! په دې خاطر چې تا د ډېرو خلکو وینه تویه کړې ده او بتانو ته په عبادت کولو سره دې خپل ځان ناپاکه کړی دی، نو ستا د سزا وخت راروان دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_3.mp3', '', 1761754199, 1761754199),
(47846, 'Ezekiel 22:4', 'Ezekiel', 22, 4, 'ته د دې وینې تویونې په سبب ګناهکار یې او د هغو بتانو په خاطر چې تا جوړ کړي دي، خپل ځان دې ناپاکه کړی دی، نو تا د خپلې سزا ورځې رانژدې کړې دي او وخت دې پوره شوی دی! ځکه نور قومونه مې پرېښودل چې ملنډې درباندې ووهي او ټول وطنونه دې مسخره کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_4.mp3', '', 1761754199, 1761754199),
(47847, 'Ezekiel 22:5', 'Ezekiel', 22, 5, 'ټول خلک د لېرې او نژدې وطنونه په تا باندې ملنډې وهي، ځکه چې ته بدنامه او ګډوډ ښار یې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_5.mp3', '', 1761754199, 1761754199),
(47848, 'Ezekiel 22:6', 'Ezekiel', 22, 6, 'د اسراییلو ټول مشران د خپل قدرت نه کار اخلي او د خلکو وینه تویوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_6.mp3', '', 1761754199, 1761754199),
(47849, 'Ezekiel 22:7', 'Ezekiel', 22, 7, 'په تا کې خلک د خپل مور او پلار سپکاوی کوي. دوی د پرديو خلکو سره زیاتی کوي او د یتیمانو او کونډو سره بد چلند کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_7.mp3', '', 1761754199, 1761754199),
(47850, 'Ezekiel 22:8', 'Ezekiel', 22, 8, 'تا زما د سپېڅلو شیانو سپکاوی کړی دی او د سبت د ورځې بې ‌عزتي دې کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_8.mp3', '', 1761754199, 1761754199),
(47851, 'Ezekiel 22:9', 'Ezekiel', 22, 9, 'ستا ځینې خلک په نورو باندې په دروغو تهمت لګوي چې ووژل شي. ځینې خلک د هغو قربانیو غوښې خوري چې په غرونو باندې بتانو ته وړاندې کیږي. ځینې په تا کې شهوت پرستي کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_9.mp3', '', 1761754199, 1761754199),
(47852, 'Ezekiel 22:10', 'Ezekiel', 22, 10, 'ځینې خلک د خپل پلار د ښځې سره څملي. ځینې خلک د میاشتیني عادت په وخت کې ښځې مجبوروي چې ورسره یوځای شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_10.mp3', '', 1761754199, 1761754199),
(47853, 'Ezekiel 22:11', 'Ezekiel', 22, 11, 'ځینې د خپل ګاونډي د ښځې سره زنا کوي او نور د خپل زوی د ښځې سره نامشروع اړیکې لري او نور خلک خپله ناسکه خور مجبوروي چې ورسره څملي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_11.mp3', '', 1761754199, 1761754199),
(47854, 'Ezekiel 22:12', 'Ezekiel', 22, 12, 'ستا ځینې خلک د رشوت په بدل کې وینه تویوي. ځینې خلک چې خپلو اسراییلیانو ورونو ته پور ورکوي، نو د هغه سود اخلي او د هغو نه د مال په غصب کولو سره خپل ځانونه شتمن کوي. هغوی زه هېر کړی یم. څښتن تعالی داسې ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_12.mp3', '', 1761754199, 1761754199),
(47855, 'Ezekiel 22:13', 'Ezekiel', 22, 13, 'ګوره، په دې خاطر چې تا نامشروع ګټې کړې دي او د هغو وینو تویونو له امله چې په تا کې شوي دي، زه به خپل لاس په تا باندې اوچت کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_13.mp3', '', 1761754199, 1761754199),
(47856, 'Ezekiel 22:14', 'Ezekiel', 22, 14, 'کله چې زه تا سره خپل حساب تصفیه کړم، نو ته به خپل همت له لاسه ورکړې او دومره به کمزوری شې چې ته به ونه شې کولای خپل لاسونه اوچت کړې. ما څښتن داسې وویل. څه چې ما وویل زه به هماغسې وکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_14.mp3', '', 1761754199, 1761754199),
(47857, 'Ezekiel 22:15', 'Ezekiel', 22, 15, 'زه به ستا خلک په نورو قومونو او وطنونو کې خواره واره کړم او ستا ناپاکي‎ به له منځه یوسم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_15.mp3', '', 1761754199, 1761754199),
(47858, 'Ezekiel 22:16', 'Ezekiel', 22, 16, 'نور قومونه به ستا د خلکو د کارونو له امله ستا سپکاوی کوي، خو ته به پوه شې چې زه څښتن یم.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_16.mp3', '', 1761754199, 1761754199),
(47859, 'Ezekiel 22:17', 'Ezekiel', 22, 17, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_17.mp3', '', 1761754199, 1761754199),
(47860, 'Ezekiel 22:18', 'Ezekiel', 22, 18, '«ای فاني انسانه، اسراییلیان ماته د بېکاره برنجو، قلعي، اوسپنې او سرپو په شان شوي دي چې په داش کې د سپینو زرو د چڼولو نه وروسته بېلیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_18.mp3', '', 1761754199, 1761754199),
(47861, 'Ezekiel 22:19', 'Ezekiel', 22, 19, 'نو زه څښتن تعالی تاسو ته داسې وایم چې تاسو د هماغو شیانو په شان بېکاره یئ. نو زه به تاسو ټول په اورشلیم کې راټول کړم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_19.mp3', '', 1761754199, 1761754199),
(47862, 'Ezekiel 22:20', 'Ezekiel', 22, 20, 'لکه څنګه چې سپین زر، برنج، اوسپنه، سرپ او حلبي په داش کې اچوي او اور تېزوي، ترڅو ویلي یې کړي. زما قهر او غضب به تاسو داسې ویلي کړي لکه څنګه چې اور فلزي مواد ویلي کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_20.mp3', '', 1761754199, 1761754199),
(47863, 'Ezekiel 22:21', 'Ezekiel', 22, 21, 'هو، زه به تاسو په اورشلیم کې سره راټول کړم، په تاسو باندې به د خپل قهر اور تېز کړم او تاسو به ویلي کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_21.mp3', '', 1761754199, 1761754199),
(47864, 'Ezekiel 22:22', 'Ezekiel', 22, 22, 'تاسو به په اورشلیم کې داسې ویلي شئ لکه سپین زر چې په داش کې ویلي کیږي، نو بیا به تاسو ته د څښتن قهر درمعلوم شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_22.mp3', '', 1761754199, 1761754199),
(47865, 'Ezekiel 22:23', 'Ezekiel', 22, 23, 'څښتن یوځل بیا ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_23.mp3', '', 1761754199, 1761754199),
(47866, 'Ezekiel 22:24', 'Ezekiel', 22, 24, '«ای فاني انسانه، د اسراییلو هېواد ته ووایه چې ته ناپاکه هېواد یې او زما د قهر په وخت کې به په تا باران ونه اوریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_24.mp3', '', 1761754199, 1761754199),
(47867, 'Ezekiel 22:25', 'Ezekiel', 22, 25, 'د اسراییلو پیغمبران دسیسې جوړوي. هغوی د هغو زمریانو په شان دي چې په هغو حیواناتو باندې غوریږي چې هغوی وژلي دي. هغوی خلک وژلي، پیسې او جایداد یې ورڅخه اخیستی دی او په خپلو قتلونو سره یې په هېواد کې ډېرې ښځې کونډې کړې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_25.mp3', '', 1761754199, 1761754199),
(47868, 'Ezekiel 22:26', 'Ezekiel', 22, 26, 'کاهنان زما قانون ماتوي او د سپېڅلو شیانو بې ‌عزتي کوي. هغوی د سپېڅلو او عادي شیانو تر منځ فرق نه کوي او د پاکو او ناپاکو شیانو د توپیر په اړه تعلیم نه ورکوي. د سبت د ورځې پروا نه ساتي. نو نتیجه یې دا شوه چې د اسراییلو خلک زما سپکاوی کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_26.mp3', '', 1761754199, 1761754199),
(47869, 'Ezekiel 22:27', 'Ezekiel', 22, 27, 'د هغوی مشران د هغو لېوانو په شان دي چې کوم حیوانات چې د هغوی وینه دې تویه کړې وي، هغه ټوټې ټوټې کوي. هغوی د دې دپاره دا قتلونه کوي چې نامشروع ګټه تر‌لاسه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_27.mp3', '', 1761754199, 1761754199),
(47870, 'Ezekiel 22:28', 'Ezekiel', 22, 28, 'پیغمبرانو دا ګناهونه داسې پټ کړي او سپین کړي دي، لکه څوک چې په چونه باندې دېوال سپینوي. هغوی د دې مشرانو دپاره غلطې رویاګانې ویني او د دروغو پېشګویانې کوي. هغوی دعوه کوي چې دوی د څښتن تعالی له خوا خبرې کوي، خو ما څښتن د هغوی سره خبرې نه دې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_28.mp3', '', 1761754199, 1761754199),
(47871, 'Ezekiel 22:29', 'Ezekiel', 22, 29, 'د اسراییلو خلک غصب او غلا کوي. هغوی د غریبانو سره ظلم کوي او د پردیو خلکو سره زورزیاتی او د هغوی نه غلطه ګټه اخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_29.mp3', '', 1761754199, 1761754199),
(47872, 'Ezekiel 22:30', 'Ezekiel', 22, 30, 'ما په هغوی کې یو داسې کس لټاوه چې دېوال جوړ کړي او په هغه ځای کې ودریږي چې دېوالونه راغورځېدلي وي او کله چې زه د خپل قهر په وخت کې دا وطن ورانوم د هغه نه دفاع وکړي، خو هېڅوک مې پیدا نه کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_30.mp3', '', 1761754199, 1761754199),
(47873, 'Ezekiel 22:31', 'Ezekiel', 22, 31, 'نو زه به په هغوی باندې خپل قهر نازل کړم او د هغو کارونو سره سم چې هغوی کړي دي، د خپل غضب په اور کې به یې له منځه یوسم.» څښتن تعالی داسې ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel22_verse_31.mp3', '', 1761754199, 1761754199),
(47874, 'Ezekiel 15:1', 'Ezekiel', 15, 1, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel15_verse_1.mp3', '', 1761754199, 1761754199),
(47875, 'Ezekiel 15:2', 'Ezekiel', 15, 2, '«ای فاني انسانه، د انګورو د شکولو نه وروسته د انګورو د تاکونو ځینې لرګي چې پرې کیږي، نو د هغه به څه ګټه وي؟ هغه لرګي د ځنګل د نورو ونو د لرګیو په شان نه دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel15_verse_2.mp3', '', 1761754199, 1761754199),
(47876, 'Ezekiel 15:3', 'Ezekiel', 15, 3, 'ایا د هغه د لرګي نه د کوم شي په جوړولو کې کار اخیستلی شئ؟ ایا د هغه نه د شیانو د ځوړندولو دپاره موږی جوړولی شئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel15_verse_3.mp3', '', 1761754199, 1761754199),
(47877, 'Ezekiel 15:4', 'Ezekiel', 15, 4, 'په یقین سره هغه یوازې د اور د بلولو دپاره ښه دي. کله چې د هغه دواړه سرونه وسوځي او منځ یې سکاره شي، نو د هغه نه کوم شی جوړولی شې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel15_verse_4.mp3', '', 1761754199, 1761754199),
(47878, 'Ezekiel 15:5', 'Ezekiel', 15, 5, 'هغه د سوځېدلو نه مخکې بې‌ګټې ؤ. اوس چې هغه په اور کې وسوځېده او سکاره شو، نو هغه نور هم بې‌ګټې شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel15_verse_5.mp3', '', 1761754199, 1761754199),
(47879, 'Ezekiel 15:6', 'Ezekiel', 15, 6, 'نو څښتن تعالی داسې وایي: ‹لکه څنګه چې مې د تاک لرګي د ځنګل د ونو څخه د سوځولو دپاره تیار کړي دي، همداسې مې د اورشلیم خلک هم د سزا دپاره تیار کړي دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel15_verse_6.mp3', '', 1761754199, 1761754199),
(47880, 'Ezekiel 15:7', 'Ezekiel', 15, 7, 'او هغوی ته به سزا ورکړم. که هغوی د یو اور نه ځان خلاص کړ، خو بل اور به یې وسوځوي. کله چې زه هغوی ته سزا ورکړم، نو بیا به تاسو پوه شئ چې زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel15_verse_7.mp3', '', 1761754199, 1761754199),
(47881, 'Ezekiel 15:8', 'Ezekiel', 15, 8, 'د هغوی هېواد به وران او ویجاړ کړم، ځکه چې هغوی ماته وفادار نه وو. څښتن تعالی داسې ویلي دي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel15_verse_8.mp3', '', 1761754199, 1761754199),
(47882, 'Ecclesiastes 1:1', 'Ecclesiastes', 1, 1, 'دا د هغه څېړونکي خبرې دي چې د داود زوی دی او په اورشلیم کې پاچا ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes1_verse_1.mp3', '', 1761754199, 1761754199),
(47883, 'Ecclesiastes 1:2', 'Ecclesiastes', 1, 2, 'دا څېړونکی وایي: «لوګی او پوکی! لوګی او پوکی! نو دا هرڅه لوګي او پوکي دي!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes1_verse_2.mp3', '', 1761754199, 1761754199),
(47884, 'Ecclesiastes 1:3', 'Ecclesiastes', 1, 3, 'انسان چې د اسمان لاندې زیار او زحمت وباسي نو بیا ګټه یې څه ده؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes1_verse_3.mp3', '', 1761754199, 1761754199),
(47885, 'Ecclesiastes 1:4', 'Ecclesiastes', 1, 4, 'نسلونه به ځي او نور نسلونه به د هغوی په ځای راځي خو ځمکه به تر ډېره وخته پاتې وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes1_verse_4.mp3', '', 1761754199, 1761754199),
(47886, 'Ecclesiastes 1:5', 'Ecclesiastes', 1, 5, 'لمر راخېژي او بېرته پرېوځي او بېرته د یو اتل په شان ستومانه هغه ځای ته ځي چې بیا له هغه ځایه راوخېژي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes1_verse_5.mp3', '', 1761754199, 1761754199),
(47887, 'Ecclesiastes 1:6', 'Ecclesiastes', 1, 6, 'باد د جنوب خواته لګیږي بیا تاویږي، د شمال په لور ځي او همداسې تاویږي راتاویږي بیا بېرته په خپله لاره راسمیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes1_verse_6.mp3', '', 1761754199, 1761754199),
(47888, 'Ecclesiastes 1:7', 'Ecclesiastes', 1, 7, 'ټول سیندونه د بحیرې په لور بهیږي خو بحیره هېڅکله نه ډکیږي له هغه ځایه چې د سیند اوبه بهیږي بیا بېرته همدا اوبه هلته روانیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes1_verse_7.mp3', '', 1761754199, 1761754199),
(47889, 'Ecclesiastes 1:8', 'Ecclesiastes', 1, 8, 'ټول شیان دي ستومانه او بې‌خونده چې بیان یې له وسه دی بهر نه سترګې مړې شوې له کتلو نه غوږونه دي ډک شوي له اورېدلو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes1_verse_8.mp3', '', 1761754199, 1761754199),
(47890, 'Ecclesiastes 1:9', 'Ecclesiastes', 1, 9, 'هرڅه چې اوس موجود دي لا به موجود وي او څه چې وو پېښ شوي په پخوانیو زمانو کې بیا به تکرار شي نو هېڅ کوم نوی شی به نه وي د اسمان لاندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes1_verse_9.mp3', '', 1761754199, 1761754199),
(47891, 'Ecclesiastes 1:10', 'Ecclesiastes', 1, 10, 'داسې څه به وي چې څوک وویلی شي: «وګوره، دا شی نوی نه دی؟» خو هغه هم له پخوا نه موجود ؤ کلونه مخکې له مونږ نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes1_verse_10.mp3', '', 1761754199, 1761754199),
(47892, 'Ecclesiastes 1:11', 'Ecclesiastes', 1, 11, 'تېر نسلونه د هېچا په یاد نه دي او حتی هغه راتلونکي نسلونه چې لا نه دي پیدا شوي هغوی به هم همداسې هېر شي له هغو خلکو نه چې راځي هغوی نه وروسته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes1_verse_11.mp3', '', 1761754199, 1761754199),
(47893, 'Ecclesiastes 1:12', 'Ecclesiastes', 1, 12, 'زه څېړونکی په اورشلیم کې د اسراییلو پاچا وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes1_verse_12.mp3', '', 1761754199, 1761754199),
(47894, 'Ecclesiastes 1:13', 'Ecclesiastes', 1, 13, 'ما پرېکړه وکړه چې په ټوله نړۍ کې چې هرڅه تر‌سره کیږي ولټوم او هغه په حکمت سره وڅېړم. نو بیا پوه شوم چې خدای د سختو کارونو او تکلیفونو دروند بار د انسانانو په اوږو ایښی دی چې پرې بوخت وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes1_verse_13.mp3', '', 1761754199, 1761754199),
(47895, 'Ecclesiastes 1:14', 'Ecclesiastes', 1, 14, 'ما دا هرڅه چې د اسمان لاندې تر‌سره کیږي، لیدلي دي. نو وګوره چې دا هرڅه لوګي او پوکي او په باد پسې منډې وهل دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes1_verse_14.mp3', '', 1761754199, 1761754199),
(47896, 'Ecclesiastes 1:15', 'Ecclesiastes', 1, 15, 'کوږ شی هېڅکله نه شي سمېدلی او ناموجود شی نه شي شمارېدلی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes1_verse_15.mp3', '', 1761754199, 1761754199),
(47897, 'Ecclesiastes 1:16', 'Ecclesiastes', 1, 16, 'له ځان سره مې وویل: «وګوره، زه دومره پوه او هوښیار سړی شوی یم چې زما څخه مخکې په اورشلیم کې هېڅوک داسې هوښیار نه ؤ تېر شوی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes1_verse_16.mp3', '', 1761754199, 1761754199),
(47898, 'Ecclesiastes 1:17', 'Ecclesiastes', 1, 17, 'نو پرېکړه مې وکړه چې حکمت وپېژنم او تر‌څنګ یې جهالت او حماقت هم وپېژنم، خو زه دې نتیجې ته ورسېدم چې دا کار هم په باد پسې منډې وهل دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes1_verse_17.mp3', '', 1761754199, 1761754199),
(47899, 'Ecclesiastes 1:18', 'Ecclesiastes', 1, 18, 'څومره چې د چا حکمت لوړیږي نو هغومره یې کړاوونه هم ډېریږي او هغه څوک چې خپله پوهه لوړوي نو خپل دردونه ډېروي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes1_verse_18.mp3', '', 1761754199, 1761754199),
(47900, 'Ezekiel 3:1', 'Ezekiel', 3, 1, 'څښتن وویل: «ای فاني انسانه، دا طومار چې ستا په مخکې دی، هغه وخوره، بیا د اسراییلو قوم ته ورشه او د هغوی سره خبرې وکړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_1.mp3', '', 1761754199, 1761754199),
(47901, 'Ezekiel 3:2', 'Ezekiel', 3, 2, 'نو ما خپله خوله خلاصه کړه او هغه راته طومار راکړ چې ویې خورم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_2.mp3', '', 1761754199, 1761754199),
(47902, 'Ezekiel 3:3', 'Ezekiel', 3, 3, 'هغه وویل: «ای فاني انسانه، دا طومار چې زه یې درکوم هغه وخوره، خپله خېټه دې ورباندې ډکه کړه.» نو هغه مې وخوړ او هغه زما په خوله کې د شاتو په شان خوږ ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_3.mp3', '', 1761754199, 1761754199),
(47903, 'Ezekiel 3:4', 'Ezekiel', 3, 4, 'بیا هغه ماته وویل: «ای فاني انسانه، د اسراییلو قوم ته ورشه او زما خبرې هغوی ته ووایه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_4.mp3', '', 1761754199, 1761754199),
(47904, 'Ezekiel 3:5', 'Ezekiel', 3, 5, 'ځکه زه تا داسې قوم ته نه لېږم چې هغوی په کومې پردۍ او سختې ژبې خبرې کوي، بلکې د اسراییلو قوم ته دې لېږم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_5.mp3', '', 1761754199, 1761754199),
(47905, 'Ezekiel 3:6', 'Ezekiel', 3, 6, 'که چېرې ته مې داسې ډېرو قومونو ته لېږلی وای چې په سختو ژبو یې خبرې کولې چې ته ورباندې نه پوهېدلې، بیاهم هغوی به تاته غوږ نیولی وای.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_6.mp3', '', 1761754199, 1761754199),
(47906, 'Ezekiel 3:7', 'Ezekiel', 3, 7, 'خو د اسراییلو قوم نه غواړي چې ستا خبرو ته غوږ ونیسي، حتی هغوی نه غواړي چې زما خبرو ته هم غوږ ونیسي، ځکه چې هغوی ټول سرزوري او سخت زړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_7.mp3', '', 1761754199, 1761754199),
(47907, 'Ezekiel 3:8', 'Ezekiel', 3, 8, 'خو ګوره، زه به تا هم د هغوی په شان سرزوری کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_8.mp3', '', 1761754199, 1761754199),
(47908, 'Ezekiel 3:9', 'Ezekiel', 3, 9, 'زه به دې د الماس په شان ټینګ او د تیږې څخه زیات کلک کړم. د دې سرکښه قوم او د هغوی د څېرو څخه مه وېرېږه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_9.mp3', '', 1761754199, 1761754199),
(47909, 'Ezekiel 3:10', 'Ezekiel', 3, 10, 'څښتن بیا راته وویل: «ای فاني انسانه، زما کلام ته په غور سره پام کوه او هرڅه چې درته وایم هغه دې په زړه کې وساته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_10.mp3', '', 1761754199, 1761754199),
(47910, 'Ezekiel 3:11', 'Ezekiel', 3, 11, 'بیا دې خپلو وطندارانو ته چې په جلاوطنۍ کې اوسیږي، ورشه او هغوی ته ووایه چې ته زما یعنې څښتن خدای له خوا یو پیغام لرې. دا کار وکړه، که هغوی درته غوږ نیوه یا یې نه نیوه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_11.mp3', '', 1761754199, 1761754199);